static Status need_u64(const LgoObjectView&v,u32 id,u64*out=nullptr){u64 x{};auto st=lgo_get_u64(v,id,&x);if(st==Status::Ok&&out)*out=x;return st;}static Status need_text(const LgoObjectView&v,u32 id,std::string*out=nullptr){std::string x;auto st=lgo_get_utf8(v,id,&x);if(st==Status::Ok&&out)*out=x;return st;}static Status need_digest(const LgoObjectView&v,u32 id,Digest256*out=nullptr){Digest256 x{};auto st=lgo_get_digest(v,id,&x);if(st==Status::Ok&&out)*out=x;return st;}Status graph_get_node(const GraphState&g,std::string_view id,const NodeEntry**out){if(!out)return Status::InvalidArgument;auto it=g.nodes.find(std::string(id));if(it==g.nodes.end())return Status::NodeMissing;*out=&it->second;return Status::Ok;}Status graph_load_node(const GraphState&g,const ObjectStore&s,std::string_view id,Buffer*b,LgoObjectView*v){const NodeEntry*n{};auto st=graph_get_node(g,id,&n);if(st!=Status::Ok)return st;if((st=object_get(&s,n->revision_digest,b))!=Status::Ok)return st;return lgo_parse({b->data(),(u64)b->size()},v);}static bool active_lifecycle(Lifecycle l){return l!=Lifecycle::RETIRED;}static Status existing_type(const GraphState&g,std::string_view id,NodeType t){const NodeEntry*n{};auto st=graph_get_node(g,id,&n);return st==Status::Ok&&n->type==t?Status::Ok:Status::NodeMissing;}
Status graph_validate_node_contract(const GraphState&g,const ObjectStore&s,const LgoObjectView&v){u64 rk{},nt{},rev{},life{};std::string id;if(need_u64(v,F_RECORD_KIND,&rk)!=Status::Ok||rk!=(u64)RecordKind::NODE)return Status::InvariantViolation;if(need_u64(v,F_NODE_TYPE,&nt)!=Status::Ok||nt<1||nt>11)return Status::Unsupported;if(need_text(v,F_SEMANTIC_ID,&id)!=Status::Ok||!valid_semantic_id(id))return Status::InvalidArgument;if(need_u64(v,F_REVISION,&rev)!=Status::Ok||!rev)return Status::BadRevision;if(need_u64(v,F_LIFECYCLE,&life)!=Status::Ok||life<1||life>7)return Status::InvariantViolation;NodeType t=(NodeType)nt;std::string a,b,scope,pred,prov,status;Digest256 d{};u64 x{},vk{};switch(t){case NodeType::SOURCE:if(need_text(v,F_TITLE)!=Status::Ok||need_text(v,F_ATTRIBUTION)!=Status::Ok||need_text(v,F_SOURCE_CLASS)!=Status::Ok)return Status::InvariantViolation;break;case NodeType::WITNESS:if(need_digest(v,F_OBJECT_DIGEST,&d)!=Status::Ok||need_text(v,F_REF_A_ID,&a)!=Status::Ok)return Status::InvariantViolation;if(existing_type(g,a,NodeType::SOURCE)!=Status::Ok)return Status::NodeMissing;if(blob_verify(&s,d)!=Status::Ok)return Status::ObjectNotFound;break;case NodeType::PASSAGE:if(need_digest(v,F_OBJECT_DIGEST,&d)!=Status::Ok||need_text(v,F_LOCATOR)!=Status::Ok||need_text(v,F_VALUE_TEXT)!=Status::Ok||need_text(v,F_REF_A_ID,&a)!=Status::Ok)return Status::InvariantViolation;if(existing_type(g,a,NodeType::WITNESS)!=Status::Ok)return Status::NodeMissing;if(blob_verify(&s,d)!=Status::Ok)return Status::ObjectNotFound;break;case NodeType::CLAIM:if(need_u64(v,F_EPISTEMIC_STATE,&x)!=Status::Ok||x<1||x>10)return Status::InvariantViolation;if(need_text(v,F_SCOPE,&scope)!=Status::Ok||scope.empty())return Status::ScopeMissing;if(need_text(v,F_SUBJECT_ID)!=Status::Ok||need_text(v,F_PREDICATE,&pred)!=Status::Ok||pred.empty())return Status::InvariantViolation;if(need_u64(v,F_VALUE_KIND,&vk)!=Status::Ok||(vk!=1&&vk!=2))return Status::InvariantViolation;if((vk==1&&need_text(v,F_VALUE_TEXT)!=Status::Ok)||(vk==2&&need_u64(v,F_VALUE_U64)!=Status::Ok))return Status::InvariantViolation;if(need_text(v,F_PROVENANCE_ID,&prov)!=Status::Ok||g.nodes.find(prov)==g.nodes.end())return Status::ProvenanceMissing;if(need_text(v,F_CLAIM_CLASS)!=Status::Ok)return Status::InvariantViolation;break;case NodeType::IMPLEMENTATION:if(need_text(v,F_TITLE)!=Status::Ok||need_text(v,F_SCOPE,&scope)!=Status::Ok||scope.empty())return Status::ScopeMissing;break;case NodeType::COURT:if(need_text(v,F_TITLE)!=Status::Ok||need_text(v,F_SCOPE,&scope)!=Status::Ok||need_text(v,F_REF_A_ID,&a)!=Status::Ok||need_u64(v,F_COURT_DENOMINATOR)!=Status::Ok)return Status::InvariantViolation;if(existing_type(g,a,NodeType::IMPLEMENTATION)!=Status::Ok)return Status::NodeMissing;break;case NodeType::OBSERVATION:if(need_text(v,F_REF_A_ID,&a)!=Status::Ok||existing_type(g,a,NodeType::COURT)!=Status::Ok)return Status::NodeMissing;if(need_text(v,F_SCOPE,&scope)!=Status::Ok||need_text(v,F_PREDICATE,&pred)!=Status::Ok||need_u64(v,F_VALUE_KIND,&vk)!=Status::Ok)return Status::InvariantViolation;if(pred.rfind("conclusion:",0)==0)return Status::InvariantViolation;if((vk==1&&need_text(v,F_VALUE_TEXT)!=Status::Ok)||(vk==2&&need_u64(v,F_VALUE_U64)!=Status::Ok))return Status::InvariantViolation;break;case NodeType::EVIDENCE:if(need_text(v,F_REF_A_ID,&a)!=Status::Ok||need_text(v,F_REF_B_ID,&b)!=Status::Ok||need_u64(v,F_RELATION_CODE,&x)!=Status::Ok||need_text(v,F_SCOPE,&scope)!=Status::Ok)return Status::InvariantViolation;if(existing_type(g,a,NodeType::OBSERVATION)!=Status::Ok||existing_type(g,b,NodeType::CLAIM)!=Status::Ok)return Status::InvariantViolation;if(x!=(u64)RelationCode::SUPPORTS&&x!=(u64)RelationCode::CONTRADICTS)return Status::Unsupported;break;case NodeType::CONTRADICTION:if(need_text(v,F_MEMBER_A_ID,&a)!=Status::Ok||need_text(v,F_MEMBER_B_ID,&b)!=Status::Ok||need_text(v,F_STATUS,&status)!=Status::Ok)return Status::InvariantViolation;if(existing_type(g,a,NodeType::CLAIM)!=Status::Ok||existing_type(g,b,NodeType::CLAIM)!=Status::Ok)return Status::NodeMissing;if(status!="OPEN")return Status::InvariantViolation;break;case NodeType::PRINCIPLE:if(need_u64(v,F_MATURITY,&x)!=Status::Ok||x>5||need_text(v,F_VALUE_TEXT)!=Status::Ok||need_text(v,F_SCOPE,&scope)!=Status::Ok)return Status::InvariantViolation;if(x>=2){if(need_text(v,F_REF_A_ID,&a)!=Status::Ok||existing_type(g,a,NodeType::EVIDENCE)!=Status::Ok)return Status::ProvenanceMissing;}if(x==5&&(need_text(v,F_FALSIFICATION_CONDITION)!=Status::Ok||need_text(v,F_APPLICABILITY_BOUNDARY)!=Status::Ok))return Status::InvariantViolation;break;case NodeType::VIEW:{if(need_u64(v,F_VIEW_TYPE,&x)!=Status::Ok||(x!=1&&x!=2)||need_digest(v,F_GRAPH_ROOT)!=Status::Ok)return Status::InvariantViolation;std::vector<Digest256>ds;if(lgo_get_digest_list(v,F_BODY_DIGEST,&ds)!=Status::Ok)return Status::InvariantViolation;break;}}return Status::Ok;}
static Status parse_node_core(const LgoObjectView&v,std::string*id,u64*rev,NodeType*t,Lifecycle*l){u64 nt{},lf{};if(need_text(v,F_SEMANTIC_ID,id)!=Status::Ok||need_u64(v,F_REVISION,rev)!=Status::Ok||need_u64(v,F_NODE_TYPE,&nt)!=Status::Ok||need_u64(v,F_LIFECYCLE,&lf)!=Status::Ok)return Status::InvariantViolation;*t=(NodeType)nt;*l=(Lifecycle)lf;return Status::Ok;}static std::string edge_key(std::string_view a,RelationCode r,std::string_view b,std::string_view scope){std::string k="E";k.push_back('\0');k.append(a);k.push_back('\0');u8 x[4];put_u32_le(x,(u32)r);k.append((const char*)x,4);k.append(b);k.push_back('\0');k.append(scope);return k;}static Status parse_edge(const LgoObjectView&v,EdgeEntry*out){u64 rk{},rc{};std::string a,b,s;if(need_u64(v,F_RECORD_KIND,&rk)!=Status::Ok||rk!=(u64)RecordKind::EDGE)return Status::InvariantViolation;if(need_text(v,F_REF_A_ID,&a)!=Status::Ok||need_text(v,F_REF_B_ID,&b)!=Status::Ok||need_u64(v,F_RELATION_CODE,&rc)!=Status::Ok||rc<1||rc>10)return Status::InvariantViolation;if(lgo_get_utf8(v,F_SCOPE,&s)!=Status::Ok)s.clear();out->from_id=a;out->to_id=b;out->scope=s;out->relation=(RelationCode)rc;out->canonical_key=edge_key(a,(RelationCode)rc,b,s);out->edge_digest=v.digest;return Status::Ok;}
Status graph_apply_event(GraphState*g,const ObjectStore*s,const LglRecord&r){if(!g||!s)return Status::InvalidArgument;Buffer b;auto st=object_get(s,r.payload_object_digest,&b);if(st!=Status::Ok)return st;LgoObjectView v{};if((st=lgo_parse({b.data(),(u64)b.size()},&v))!=Status::Ok)return st;if(r.event_type==(u32)EventType::REJECTION_RECORDED){u64 rk{};if(need_u64(v,F_RECORD_KIND,&rk)!=Status::Ok||rk!=(u64)RecordKind::REJECTION)return Status::InvariantViolation;g->rejections.push_back(v.digest);return Status::Ok;}if(r.event_type==(u32)EventType::EDGE_ADDED||r.event_type==(u32)EventType::EDGE_RETIRED){EdgeEntry e{};if((st=parse_edge(v,&e))!=Status::Ok)return st;if(g->nodes.find(e.from_id)==g->nodes.end()||g->nodes.find(e.to_id)==g->nodes.end())return Status::NodeMissing;if(r.event_type==(u32)EventType::EDGE_ADDED){if(g->edges.count(e.canonical_key))return Status::EdgeExists;g->edges[e.canonical_key]=e;}else{auto it=g->edges.find(e.canonical_key);if(it==g->edges.end())return Status::EdgeMissing;g->edges.erase(it);}return Status::Ok;}if((st=graph_validate_node_contract(*g,*s,v))!=Status::Ok)return st;std::string id;u64 rev{};NodeType nt{};Lifecycle lf{};if((st=parse_node_core(v,&id,&rev,&nt,&lf))!=Status::Ok)return st;auto it=g->nodes.find(id);if(r.event_type==(u32)EventType::NODE_CREATED){if(it!=g->nodes.end())return Status::NodeExists;if(rev!=1)return Status::BadRevision;g->nodes[id]={id,rev,v.digest,nt,lf};return Status::Ok;}if(r.event_type==(u32)EventType::NODE_REVISED){if(it==g->nodes.end())return Status::NodeMissing;if(rev!=it->second.revision+1)return Status::BadRevision;it->second={id,rev,v.digest,nt,lf};return Status::Ok;}if(r.event_type==(u32)EventType::VIEW_PUBLISHED){if(nt!=NodeType::VIEW)return Status::InvariantViolation;if(it==g->nodes.end()){if(rev!=1)return Status::BadRevision;g->nodes[id]={id,rev,v.digest,nt,lf};}else{if(rev!=it->second.revision+1)return Status::BadRevision;it->second={id,rev,v.digest,nt,lf};}return Status::Ok;}return Status::Unsupported;}
struct ReplayCtx{GraphState*g;const ObjectStore*s;};static Status replay_cb(const LglRecord&r,void*p){auto*c=(ReplayCtx*)p;return graph_apply_event(c->g,c->s,r);}Status graph_replay(const ObjectStore*s,const Ledger&l,GraphState*g){if(!s||!g)return Status::InvalidArgument;*g=GraphState{};ReplayCtx c{g,s};return ledger_replay(l,replay_cb,&c);}static Status append_and_apply(ObjectStore*s,Ledger*l,GraphState*g,EventType et,ByteSpan bytes,std::string_view target,Digest256*out){Digest256 od{};auto st=object_put(s,bytes,&od);if(st!=Status::Ok)return st;if((st=ledger_append(l,et,od,target,nullptr))!=Status::Ok)return st;LglRecord r{};r.event_type=(u32)et;r.payload_object_digest=od;if((st=graph_apply_event(g,s,r))!=Status::Ok)return st;if(out)*out=od;return Status::Ok;}Status graph_add_node(ObjectStore*s,Ledger*l,GraphState*g,ByteSpan bytes,Digest256*out){LgoObjectView v{};auto st=lgo_parse(bytes,&v);if(st!=Status::Ok)return st;if((st=graph_validate_node_contract(*g,*s,v))!=Status::Ok)return st;std::string id;u64 rev{},rk{};NodeType nt{};Lifecycle lf{};parse_node_core(v,&id,&rev,&nt,&lf);if(need_u64(v,F_RECORD_KIND,&rk)!=Status::Ok||rk!=(u64)RecordKind::NODE)return Status::InvariantViolation;auto it=g->nodes.find(id);if(it!=g->nodes.end())return it->second.revision_digest==v.digest?Status::NodeExists:Status::DuplicateConflict;if(rev!=1)return Status::BadRevision;return append_and_apply(s,l,g,EventType::NODE_CREATED,bytes,id,out);}Status graph_revise_node(ObjectStore*s,Ledger*l,GraphState*g,ByteSpan bytes,Digest256*out){LgoObjectView v{};auto st=lgo_parse(bytes,&v);if(st!=Status::Ok)return st;if((st=graph_validate_node_contract(*g,*s,v))!=Status::Ok)return st;std::string id;u64 rev{};NodeType nt{};Lifecycle lf{};parse_node_core(v,&id,&rev,&nt,&lf);auto it=g->nodes.find(id);if(it==g->nodes.end())return Status::NodeMissing;if(rev!=it->second.revision+1)return Status::BadRevision;return append_and_apply(s,l,g,EventType::NODE_REVISED,bytes,id,out);}Status graph_add_edge(ObjectStore*s,Ledger*l,GraphState*g,ByteSpan bytes,Digest256*out){LgoObjectView v{};auto st=lgo_parse(bytes,&v);if(st!=Status::Ok)return st;EdgeEntry e{};if((st=parse_edge(v,&e))!=Status::Ok)return st;if(g->nodes.find(e.from_id)==g->nodes.end()||g->nodes.find(e.to_id)==g->nodes.end())return Status::NodeMissing;if(g->edges.count(e.canonical_key))return g->edges[e.canonical_key].edge_digest==v.digest?Status::EdgeExists:Status::DuplicateConflict;return append_and_apply(s,l,g,EventType::EDGE_ADDED,bytes,e.canonical_key,out);}Status graph_record_rejection(ObjectStore*s,Ledger*l,GraphState*g,ByteSpan bytes,Digest256*out){LgoObjectView v{};auto st=lgo_parse(bytes,&v);if(st!=Status::Ok)return st;u64 rk{};if(need_u64(v,F_RECORD_KIND,&rk)!=Status::Ok||rk!=(u64)RecordKind::REJECTION)return Status::InvariantViolation;return append_and_apply(s,l,g,EventType::REJECTION_RECORDED,bytes,"REJECTION",out);}
Status graph_root(const GraphState&g,Digest256*out){if(!out)return Status::InvalidArgument;struct Leaf{std::string key;Digest256 digest;};std::vector<Leaf>leaves;for(auto&[id,n]:g.nodes){if(n.type==NodeType::VIEW||!active_lifecycle(n.lifecycle))continue;std::string key="N";key.push_back('\0');key+=id;Buffer x;const char*d="LOGOS:GRAPH:NODE:1";x.insert(x.end(),d,d+18);u8 len[8];put_u64_le(len,(u64)key.size());x.insert(x.end(),len,len+8);x.insert(x.end(),key.begin(),key.end());x.insert(x.end(),n.revision_digest.bytes.begin(),n.revision_digest.bytes.end());leaves.push_back({key,sha256({x.data(),(u64)x.size()})});}for(auto&[k,e]:g.edges){Buffer x;const char*d="LOGOS:GRAPH:EDGE:1";x.insert(x.end(),d,d+18);u8 len[8];put_u64_le(len,(u64)k.size());x.insert(x.end(),len,len+8);x.insert(x.end(),k.begin(),k.end());x.insert(x.end(),e.edge_digest.bytes.begin(),e.edge_digest.bytes.end());leaves.push_back({k,sha256({x.data(),(u64)x.size()})});}std::sort(leaves.begin(),leaves.end(),[](auto&a,auto&b){return a.key<b.key;});Buffer root;const char*d="LOGOS:GRAPH:ROOT:1";root.insert(root.end(),d,d+18);u8 c[8];put_u64_le(c,(u64)leaves.size());root.insert(root.end(),c,c+8);for(auto&l:leaves)root.insert(root.end(),l.digest.bytes.begin(),l.digest.bytes.end());*out=sha256({root.data(),(u64)root.size()});return Status::Ok;}Status graph_count_type(const GraphState&g,NodeType t,u64*out){if(!out)return Status::InvalidArgument;u64 n=0;for(auto&[id,x]:g.nodes){(void)id;if(x.type==t)n++;}*out=n;return Status::Ok;}
